// Prototype-only nutrition fixtures. Photos are previewed locally, never analysed or uploaded.
const mealFixtures=[
 {key:'chicken',label:'Chicken breast · cooked',match:/chicken/i,unit:'g',portion:150,base:100,calories:165,protein:31,carbs:0,fat:3.6},
 {key:'rice',label:'Rice · cooked',match:/rice/i,unit:'g',portion:200,base:100,calories:130,protein:2.7,carbs:28,fat:.3},
 {key:'vegetables',label:'Mixed vegetables',match:/vegetable|broccoli|veggies/i,unit:'g',portion:100,base:100,calories:35,protein:2,carbs:7,fat:.3},
 {key:'eggs',label:'Eggs · large',match:/eggs?/i,unit:'eggs',portion:2,base:1,calories:72,protein:6.3,carbs:.4,fat:4.8},
 {key:'toast',label:'Toast · plain',match:/toast|bread/i,unit:'slices',portion:2,base:1,calories:80,protein:3,carbs:15,fat:1},
 {key:'oats',label:'Oats · dry',match:/oats|oatmeal/i,unit:'g',portion:50,base:100,calories:389,protein:17,carbs:66,fat:7},
 {key:'yogurt',label:'Greek yogurt · plain',match:/yogurt|yoghurt/i,unit:'g',portion:150,base:100,calories:73,protein:10,carbs:4,fat:2},
 {key:'banana',label:'Banana · medium',match:/banana/i,unit:'banana',portion:1,base:1,calories:105,protein:1.3,carbs:27,fat:.4},
 {key:'oil',label:'Olive oil',match:/oil/i,unit:'g',portion:5,base:100,calories:884,protein:0,carbs:0,fat:100}
];
let mealDraft=null,mealFlowToken=0;
function draftTotal(){return mealDraft.items.reduce((a,item)=>{for(const key of ['calories','protein','carbs','fat'])a[key]+=item[key]*item.amount/item.base;return a;},{calories:0,protein:0,carbs:0,fat:0});}
function parseDemoMeal(description){
 const parts=description.replace(/\band\b/gi,',').split(/[,;+\n]/).map(x=>x.trim()).filter(Boolean),items=[],unknown=[];
 for(const part of parts){let matched=false;for(const fixture of mealFixtures){if(!fixture.match.test(part))continue;matched=true;let amount=fixture.portion,explicit=false;const grams=part.match(/(\d+(?:\.\d+)?)\s*(?:g\b|grams?\b)/i),count=part.match(/\b(\d+(?:\.\d+)?)\s*(?:large\s+)?(?:eggs?|slices?|bananas?)/i);if(fixture.unit==='g'&&grams){amount=Number(grams[1]);explicit=true;}if(fixture.unit!=='g'&&count){amount=Number(count[1]);explicit=true;}const item={...fixture,match:undefined,amount,assumption:explicit?'Your portion':'Typical portion'};if(fixture.key==='rice'&&/dry|uncooked/i.test(part)){Object.assign(item,{label:'Rice · dry',calories:365,protein:7,carbs:80,fat:1});}items.push(item);}if(!matched)unknown.push(part);}
 return {items,unknown};
}
function mealModal(record,type='Breakfast',repeat=false){
 ++mealFlowToken;const v=record?.value;mealDraft={record:repeat?null:record,meal:v?.meal||type,description:v?.description||v?.name||$('#quick-note')?.value||'',photo:null,items:[],stage:'compose',notice:''};
 if(v){mealDraft.items=v.ingredients?.length?structuredClone(v.ingredients):[{key:'saved',label:v.name,amount:1,unit:'portion',base:1,calories:v.calories,protein:v.protein,carbs:v.carbs,fat:v.fat,assumption:'Saved meal'}];mealDraft.stage='review';}
 modal(record&&!repeat?'Edit your meal':'Log a meal','');$('#modal').classList.add('meal-log-dialog');paintMealFlow();
}
function paintMealFlow(){
 const d=$('#modal'),m=mealDraft;if(!m||!d.open)return;
 const head='<div class="modal-head"><div><span class="eyebrow">A LITTLE NOURISHMENT</span><h2>'+ (m.stage==='review'?'Here’s your meal.':'What’s on your plate?')+'</h2></div><button type="button" class="quiet" data-action="close-modal" aria-label="Close dialog">'+icon('close')+'</button></div>';
 const meal='<label class="meal-category">Meal <select id="meal-category">'+['Breakfast','Lunch','Dinner','Snack'].map(x=>'<option '+(m.meal===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label>';
 const notice='<p class="meal-flow-notice" role="status">'+esc(m.notice)+'</p>';
 if(m.stage==='thinking'){d.innerHTML=head+'<div class="meal-thinking" role="status"><span>✧</span><h3>Putting your meal together…</h3><p>Preparing a sample nutrition estimate.</p></div>';return;}
 if(m.stage==='compose'){
 const recent=[...new Map(records('meal').map(r=>[r.value.name,r])).values()].slice(0,4);
 d.innerHTML=head+'<p class="meal-intro">A photo, a few words, or both. Portions help; macros come next.</p>'+meal+'<div class="meal-photo-area">'+(m.photo?'<img src="'+m.photo+'" alt="Your meal photo preview"><button type="button" class="quiet" data-meal-flow="remove-photo">Remove photo</button>':'<span class="meal-photo-symbol">'+icon('food')+'</span><strong>Show us your meal</strong>')+'<div class="meal-photo-actions"><label class="meal-photo-button">Take a photo<input type="file" accept="image/*" capture="environment" data-meal-photo></label><label class="meal-photo-button">Upload photo<input type="file" accept="image/*" data-meal-photo></label></div></div><form id="meal-description-form"><label class="field">What did you eat?<textarea id="meal-description" maxlength="1000" placeholder="150g cooked chicken, 200g cooked rice, vegetables">'+esc(m.description)+'</textarea></label><p class="meal-hint">Include weights if you know them. For rice or pasta, mention cooked or dry.</p>'+notice+'<button class="primary wide" type="submit">Estimate my meal '+icon('coach')+'</button></form><div class="meal-quick-picks"><span class="eyebrow">YOUR USUALS</span><div>'+recent.map(r=>'<button type="button" data-meal-quick="'+r.id+'">'+esc(r.value.name)+'</button>').join('')+'</div></div><button type="button" class="meal-sample-link" data-meal-flow="sample">Try a sample meal →</button><p class="prototype-note">Prototype · sample estimates only. Photos stay on this device and are not analysed.</p>';
 }else{
 const t=draftTotal();d.innerHTML=head+'<div class="meal-review-top">'+(m.photo?'<img src="'+m.photo+'" alt="Your meal photo preview">':'<span class="meal-review-symbol">'+icon('food')+'</span>')+'<div><span class="badge">SAMPLE ESTIMATE</span><p>'+esc(m.description||m.items.map(i=>i.label).join(', '))+'</p></div></div>'+meal+'<div class="meal-estimate"><div><strong>'+Math.round(t.calories)+'</strong><span>kcal</span></div><div><strong>'+Math.round(t.protein)+'g</strong><span>protein</span></div><div><strong>'+Math.round(t.carbs)+'g</strong><span>carbs</span></div><div><strong>'+Math.round(t.fat)+'g</strong><span>fat</span></div></div><div class="meal-ingredients">'+m.items.map((item,i)=>'<div><span><strong>'+esc(item.label)+'</strong><small>'+esc(item.assumption)+'</small></span><label><input type="number" min="0.1" max="5000" step="0.1" value="'+item.amount+'" data-meal-amount="'+i+'" aria-label="Portion for '+esc(item.label)+'"> <span>'+esc(item.unit)+'</span></label><button type="button" class="quiet" data-meal-remove="'+i+'" aria-label="Remove '+esc(item.label)+'">'+icon('close')+'</button></div>').join('')+'</div><div class="meal-portion-chips"><button type="button" data-meal-scale="0.5">Ate half</button><button type="button" data-meal-scale="1.5">A little more</button><button type="button" data-meal-flow="describe">Edit description</button></div><form id="meal-adjust-form"><label class="field">Adjust this meal<input id="meal-adjust" maxlength="300" placeholder="Add 5g olive oil, or remove the rice"></label><button type="submit" class="quiet">Update estimate</button></form>'+notice+'<p class="meal-hint">Check the identified foods and portions. Values are illustrative, not a real AI analysis.</p><button type="button" class="primary wide" data-meal-flow="save">'+(m.record?'Save changes':'Log meal')+' '+icon('check')+'</button>';
 }
}
async function estimateDemoMeal(){
 const parsed=parseDemoMeal(mealDraft.description);if(parsed.items.some(i=>i.amount<0.1||i.amount>5000)){mealDraft.notice='Use portions between 0.1 and 5000.';paintMealFlow();return;}if(!parsed.items.length||parsed.unknown.length){mealDraft.notice=parsed.unknown.length?'This demo cannot estimate “'+parsed.unknown.join(', ')+'”. Try the sample meal, or describe chicken, rice, vegetables, eggs, toast, oats, yogurt, banana or oil.':'Add a food description, or try the sample meal below. Photos are preview-only in this prototype.';paintMealFlow();return;}
 mealDraft.items=parsed.items;mealDraft.notice='';mealDraft.stage='thinking';const token=++mealFlowToken;paintMealFlow();await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?0:700));if(token!==mealFlowToken||!$('#modal').open)return;mealDraft.stage='review';paintMealFlow();
}
document.addEventListener('input',e=>{if(e.target.id==='meal-description'&&mealDraft)mealDraft.description=e.target.value;});
document.addEventListener('change',e=>{
 const el=e.target;if(!mealDraft)return;if(el.id==='meal-category')mealDraft.meal=el.value;
 if(el.dataset.mealAmount!==undefined){const value=Number(el.value);if(!Number.isFinite(value)||value<=0||value>5000){el.setCustomValidity('Enter a portion between 0.1 and 5000.');el.reportValidity();return;}el.setCustomValidity('');mealDraft.items[Number(el.dataset.mealAmount)].amount=value;paintMealFlow();}
 if(el.hasAttribute('data-meal-photo')){const file=el.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>8*1024*1024){mealDraft.notice='Choose an image smaller than 8 MB.';paintMealFlow();return;}const token=mealFlowToken,reader=new FileReader();reader.onload=()=>{if(token!==mealFlowToken||!$('#modal').open)return;mealDraft.photo=reader.result;mealDraft.notice='Photo added. Describe the food to preview an estimate; this demo does not analyse photos.';paintMealFlow();};reader.readAsDataURL(file);}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='meal-description-form'){e.preventDefault();estimateDemoMeal();}
 if(e.target.id==='meal-adjust-form'){e.preventDefault();const adjustment=$('#meal-adjust').value.trim();if(!adjustment)return;const remove=adjustment.match(/^remove\s+(?:the\s+)?(.+)/i);if(remove){const match=mealFixtures.find(f=>f.match.test(remove[1]));if(match&&mealDraft.items.some(i=>i.key===match.key)){mealDraft.items=mealDraft.items.filter(i=>i.key!==match.key);mealDraft.notice='Ingredient removed.';}else mealDraft.notice='That ingredient was not found. You can remove it using its × button.';}else if(/^(?:i ate |ate )?half\b/i.test(adjustment)){mealDraft.items.forEach(i=>i.amount/=2);mealDraft.notice='Portions reduced by half.';}else{const parsed=parseDemoMeal(adjustment.replace(/^add\s+/i,''));if(parsed.items.length&&!parsed.unknown.length){mealDraft.items.push(...parsed.items);mealDraft.notice='Ingredients added.';}else mealDraft.notice='In this demo, try “add 5g olive oil”, “remove rice” or “ate half”.';}paintMealFlow();}
});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||!mealDraft||!$('#modal').open)return;
 if(b.dataset.mealQuick){const record=state.records.find(r=>r.id===b.dataset.mealQuick);mealModal(record,record.value.meal,true);return;}
 if(b.dataset.mealRemove!==undefined){mealDraft.items.splice(Number(b.dataset.mealRemove),1);paintMealFlow();return;}
 if(b.dataset.mealScale){mealDraft.items.forEach(i=>i.amount*=Number(b.dataset.mealScale));mealDraft.notice='Portions updated.';paintMealFlow();return;}
 const action=b.dataset.mealFlow;if(!action)return;
 if(action==='sample'){mealDraft.description='150g cooked chicken, 200g cooked rice, 100g vegetables';estimateDemoMeal();}
 if(action==='describe'){mealDraft.stage='compose';mealDraft.notice='';paintMealFlow();}
 if(action==='remove-photo'){mealDraft.photo=null;paintMealFlow();}
 if(action==='save')run(async()=>{if(!mealDraft.items.length){mealDraft.notice='Add at least one ingredient before logging.';paintMealFlow();return;}const m=mealDraft,t=draftTotal(),previous=m.record?structuredClone(m.record):null;const saved=await save('meal',{name:m.items.map(i=>i.label.split(' · ')[0]).join(', '),description:m.description,ingredients:structuredClone(m.items),meal:m.meal,quantity:1,serving:'meal',...Object.fromEntries(Object.entries(t).map(([k,v])=>[k,Math.round(v)])),estimated:true,date:selectedDate},m.record);closeModal();render();toast('Meal logged.',async()=>{state.records=state.records.filter(r=>r.id!==saved.id);if(previous)state.records.unshift(previous);render();toast('Meal undone.');});});
});
$('#modal').addEventListener('close',()=>{++mealFlowToken;$('#modal').classList.remove('meal-log-dialog');});

// Earned roster: prototype rules, distinct logging days and a rolling four-week rhythm.
const rosterRules=[
 {key:'balance',target:2,label:'2 days each of movement, meals and recovery',short:'A balanced rhythm'},
 {key:'strength',target:3,label:'Strength sessions on 3 different days',short:'Steady strength'},
 {key:'bodyweight',target:3,label:'Bodyweight or mobility sessions on 3 different days',short:'Control & mobility'},
 {key:'cardio',target:3,label:'Cardio sessions on 3 different days',short:'Your own pace'},
 {key:'meal',target:5,label:'Meals logged on 5 different days',short:'Nourishment awareness'},
 {key:'recovery',target:5,label:'Recovery check-ins on 5 different days',short:'Making room for rest'}
];
let rosterMemory={},rosterPause=null,rosterJustJoined=[];
function dayOffset(offset,from=date()){const d=new Date(from+'T12:00:00');d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function trainingKind(r){return r.value.trainingType||(/run|walk|cycle|swim|cardio/i.test(r.value.name)?'cardio':/bodyweight|mobility|calisthen|yoga/i.test(r.value.name)?'bodyweight':'strength');}
function rosterCounts(start,end){const within=state.records.filter(r=>r.value.date>=start&&r.value.date<=end),days=kind=>new Set(within.filter(r=>kind==='movement'?r.kind==='workout'&&r.value.status==='completed':['strength','bodyweight','cardio'].includes(kind)?r.kind==='workout'&&r.value.status==='completed'&&trainingKind(r)===kind:r.kind===kind).map(r=>r.value.date)).size;return {strength:days('strength'),bodyweight:days('bodyweight'),cardio:days('cardio'),meal:days('meal'),recovery:days('recovery'),balance:Math.min(days('movement'),days('meal'),days('recovery'))};}
function rosterStatus(){const end=rosterPause||date(),start=dayOffset(-27,end),counts=rosterCounts(start,end);return cast.map((c,i)=>{const rule=rosterRules[i],count=counts[rule.key],active=count>=rule.target;if(active&&!rosterMemory[i])rosterMemory[i]={earned:date()};return {...c,index:i,rule,count,active,earned:rosterMemory[i]?.earned,status:active?'Active':rosterMemory[i]?'Resting':'Discover'};});}
function rosterPortrait(i,small=false){return `<span class="roster-portrait ${small?'small':''}" aria-hidden="true" style="--persona:${i}"></span>`;}
function rosterTile(p){return `<button class="roster-member ${rosterJustJoined.includes(p.index)?"roster-new":""}" data-roster-persona="${p.index}" aria-label="${p.name}, ${p.rule.short}. View persona"><span class="roster-aura">${rosterPortrait(p.index)}</span><strong>${p.name}</strong><small>${p.rule.short}</small></button>`;}
function companionCard(){const active=rosterStatus().filter(p=>p.active);return `<section class="roster-hero" aria-label="Your active roster"><div class="roster-heading"><span class="eyebrow">YOUR ROSTER</span><span class="roster-count">${rosterPause?'On pause':active.length?active.length+' alongside you':'A fresh chapter'}</span></div>${active.length?`<div class="roster-lineup">${active.map(rosterTile).join('')}</div><p>Different strengths. Your own rhythm.</p>`:`<div class="roster-empty">${icon('coach')}<strong>A little space to grow.</strong><p>Log the habits that matter to you. Your roster takes shape over time.</p></div>`}${rosterJustJoined.length?`<div class="roster-joined-note" role="status">${rosterJustJoined.map(i=>cast[i].name).join(" & ")} joined your roster.<button data-roster-dismiss aria-label="Dismiss roster celebration">${icon("close")}</button></div>`:""}<button class="roster-link" data-view="quests">Explore your roster ${icon('arrow')}</button></section>`;}
function rosterJoinedNotice(){return rosterJustJoined.length?`<div class="roster-joined-note" role="status">${rosterJustJoined.map(i=>cast[i].name).join(" & ")} joined your roster.<button data-roster-dismiss aria-label="Dismiss roster celebration">${icon("close")}</button></div>`:"";}
function rosterOverview(){const all=rosterStatus(),live=all.filter(p=>p.active),resting=all.filter(p=>!p.active&&p.earned);return `<section class="card roster-section"><div class="card-top"><div><span class="eyebrow">HABITS, WITH A LITTLE PERSONALITY</span><h3>Your roster. Your life.</h3></div><button class="quiet" data-roster-help>How it works</button></div><p class="subtle">Build a roster that fits your life. You are not expected to earn every persona.</p>${rosterJoinedNotice()}${rosterPause?'<p class="roster-pause-note">Your roster is paused. Take the time you need; logging stays available.</p>':''}<div class="roster-gallery">${live.map(p=>`<article class="roster-earned">${rosterTile(p)}<span class="badge">${rosterPause?'PAUSED':'ACTIVE'}</span><p>${p.count} / ${p.rule.target} qualifying days in your current window</p></article>`).join('')||'<div class="roster-empty"><strong>Your first chapter starts with one entry.</strong><p>Explore a path below, or just start logging.</p></div>'}</div>${resting.length?`<details class="resting-roster"><summary>Resting companions · ${resting.length}</summary><p class="subtle">Your achievement remains. A quieter routine simply gives this persona a rest.</p><div class="resting-lineup">${resting.map(p=>`<button data-roster-persona="${p.index}">${rosterPortrait(p.index,true)}<span><strong>${p.name}</strong><small>Resting · first earned ${p.earned}</small></span></button>`).join('')}</div></details>`:''}<details class="roster-paths"><summary>Explore the different paths</summary><p class="subtle">These are possibilities, not a checklist. Follow the habits that suit you.</p><div class="roster-path-grid">${all.map(p=>`<button data-roster-persona="${p.index}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${accessoryPaths[p.index]}"/></svg><span><strong>${p.name} · ${p.rule.short}</strong><small>${p.rule.label} within 28 days</small></span></button>`).join('')}</div></details></section>`;}
function rosterInfo(i){const p=rosterStatus()[i];modal(p.name+' · '+p.role,`<div class="roster-detail-art">${rosterPortrait(i)}<span class="badge">${p.status.toUpperCase()}</span></div><p>${companionNotes[i][1].replace(/ suits .*?\./,' reflects this habit.')}</p><div class="roster-detail-progress"><strong>${p.count} / ${p.rule.target} qualifying days</strong><progress value="${Math.min(p.count,p.rule.target)}" max="${p.rule.target}" aria-label="${p.name} qualifying days"></progress><p class="subtle">${p.rule.label} within a rolling 28-day window. Multiple entries on one day count once.${i===0?' Each habit category needs two days.':''}</p></div><p class="subtle">${p.active?'This routine has earned '+p.name+' a place in your roster.':p.earned?'Your '+p.name+' achievement stays in your history. Return to this habit to bring them back.':'This path is here if it suits you. You do not need every persona.'}</p><p class="subtle">Only logged activity is reflected here; this is not a judgement of your health or identity.</p><button class="primary wide" ${i===4?'data-action="meal"':i===5?'data-action="recovery"':'data-roster-log="'+(i===0?'strength':p.rule.key)+'"'}>Log ${i===4?'a meal':i===5?'recovery':'movement'}</button>`);}
const rosterQuestOptions=[
 {name:'Build your strength rhythm',line:'Three strength days, with room to recover.',days:28,paths:[1,5],goals:{1:3,5:5}},
 {name:'Make space for nourishment',line:'A meal journal that fits your real life. No perfect meals required.',days:14,paths:[4],goals:{4:5}},
 {name:'Move your own way',line:'Explore endurance or bodyweight practice. Choose the path that fits.',days:28,paths:[3,2],goals:{3:3,2:3}},
 {name:'A little of everything',line:'Find a gentle balance between movement, nourishment and recovery.',days:28,paths:[0,5],goals:{0:2,5:5}}
];
function questRewards(paths){return `<div class="quest-roster-rewards"><span>PERSONAS THIS QUEST CAN SUPPORT</span><div>${paths.map(i=>`<button data-roster-persona="${i}" aria-label="Learn about ${cast[i].name}">${rosterPortrait(i,true)}<strong>${cast[i].name}</strong></button>`).join('')}</div></div>`;}
function rosterQuests(){const list=records('quest').filter(r=>r.value.rosterQuest!==undefined);return `<div class="page-heading"><div><span class="eyebrow">Consistency, on your terms</span><h2>Seasons & Quests</h2></div></div><section class="card quest-feature"><span class="eyebrow">YOUR LIFE. YOUR LINEUP.</span><h2>Grow into your own rhythm.</h2><p class="subtle">Personas reflect habits you nurture. Some will join you, some may rest. There is no complete set to collect.</p></section>${rosterOverview()}${activityCalendar()}<div class="section-title"><h3>Your quests</h3></div><div class="grid two">${list.map(r=>{const q=r.value,o=rosterQuestOptions[q.rosterQuest],counts=rosterCounts(q.start,q.end),ended=q.end<date();return `<section class="card quest-card"><span class="badge">${ended?'RECAP':'IN PROGRESS'}</span><h3>${o.name}</h3><p class="subtle">${pretty(q.start)} – ${pretty(q.end)}</p>${questRewards(o.paths)}<div class="quest-path-progress">${o.paths.map(i=>{const rule=rosterRules[i],count=counts[rule.key],target=o.goals[i],chosen=q.focus.includes(i),met=count>=target;return `<div><strong>${cast[i].name}<span>${met?'Qualifying rhythm reached':chosen?'Your chosen focus':'Optional path'}</span></strong><progress max="${target}" value="${Math.min(count,target)}" aria-label="${cast[i].name} quest progress"></progress><small>${count} / ${target} qualifying days</small>${ended?`<p class="subtle">${met?'This quest built the rhythm behind '+cast[i].name+'.':chosen?'This chosen routine has room to grow. Try a smaller plan next time.':'You did not pursue this path. That is completely fine.'}</p>`:''}</div>`;}).join('')}</div><button class="quiet" data-quest-recap="${r.id}">View roster recap</button><button class="quiet" data-delete="${r.id}">Remove quest</button></section>`;}).join('')||'<section class="card"><p class="subtle">Choose a quest that supports your routine.</p></section>'}</div><div class="section-title"><h3>Find your next chapter</h3></div><div class="grid two">${rosterQuestOptions.map((o,i)=>`<section class="card quest-card"><span class="eyebrow">${o.days}-day chapter</span><h3>${o.name}</h3><p class="subtle">${o.line}</p>${questRewards(o.paths)}<button class="primary" data-roster-quest="${i}">Explore quest ${icon('arrow')}</button></section>`).join('')}</div>`;}
function questRecap(id){const q=state.records.find(r=>r.id===id)?.value;if(!q)return;const o=rosterQuestOptions[q.rosterQuest],counts=rosterCounts(q.start,q.end),end=q.end<date();modal(end?'Your quest, reflected.':'Your chapter so far.',`<p class="subtle">${o.name} · ${end?'Completed window':'Progress recap'}</p><div class="roster-recap">${o.paths.map(i=>{const met=counts[rosterRules[i].key]>=o.goals[i];return `<div>${rosterPortrait(i,true)}<span><strong>${cast[i].name} · ${met?'Rhythm reached':q.focus.includes(i)?'Still growing':'Optional path'}</strong><p>${met?counts[rosterRules[i].key]+' qualifying days supported this persona.':q.focus.includes(i)?counts[rosterRules[i].key]+' / '+o.goals[i]+' days toward your chosen focus.':"This was not one of your chosen goals."}</p></span></div>`;}).join('')}</div><p class="subtle">Quest results stay in this chapter. Your active roster reflects the latest 28 days, so a past achievement may now be resting.</p>`);}
function seedRosterDemo(id){rosterMemory={};rosterPause=null;rosterJustJoined=[];if(id==='sam')return;const add=(kind,value)=>state.records.push({id:uuid(),kind,value,version:1,updated:Date.now()});for(const n of id==='maya'?[1,4,7]:[2,6,10])add('workout',{name:id==='maya'?'Easy walk':'Full Body',trainingType:id==='maya'?'cardio':'strength',date:dayOffset(-n),status:'completed',unit:'kg',exercises:[],startedAt:null,finishedAt:null});for(const n of [1,3,5,8]){add('meal',{date:dayOffset(-n),meal:'Lunch',name:'A nourishing bowl',quantity:1,serving:'bowl',calories:520,protein:25,carbs:65,fat:18});add('recovery',{date:dayOffset(-n),sleep:7.5,water:2,energy:3,notes:''});}rosterMemory[id==='maya'?1:3]={earned:dayOffset(-42)};add('quest',{rosterQuest:id==='maya'?2:0,focus:[id==='maya'?3:1],start:dayOffset(-13),end:dayOffset(14),name:rosterQuestOptions[id==='maya'?2:0].name});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-roster-dismiss')){rosterJustJoined=[];render();return;}if(b.hasAttribute('data-roster-help'))modal('A roster, not a checklist.',`<p>Personas join through consistent logging across different days. Your active roster reflects a rolling 28-day window.</p><p>When a routine becomes quieter, that persona rests. Your achievement remains in history, and returning to the habit reactivates it.</p><p>You are not expected to earn everyone. These reflect logged habits, not fitness ability, body shape or nutritional quality.</p><p class="subtle">Pause your roster in Settings during travel, illness or any time you need space. It freezes the evaluation window; logging remains available.</p>`);if(b.dataset.rosterPersona!==undefined)rosterInfo(Number(b.dataset.rosterPersona));if(b.dataset.questRecap)questRecap(b.dataset.questRecap);if(b.dataset.rosterQuest!==undefined){const i=Number(b.dataset.rosterQuest),o=rosterQuestOptions[i];modal('Choose your focus',`<h3>${o.name}</h3><p>${o.line}</p><form id="roster-quest-form" data-index="${i}"><p class="subtle">Choose at least one path. Other personas are possibilities, never requirements. Reaching a path’s rhythm can activate or strengthen that persona in your roster.</p>${o.paths.map((p,j)=>`<label class="quest-focus-option"><input type="checkbox" name="focus" value="${p}" ${j===0?'checked':''}><span><strong>${cast[p].name} · ${rosterRules[p].short}</strong><small>${rosterRules[p].label} during this ${o.days}-day chapter</small></span></label>`).join('')}<button type="submit" class="primary wide">Begin this chapter</button></form>`);}if(b.dataset.rosterLog){modal('Log your movement',`<p class="subtle">A completed session counts once per day. Duration is for your journal, not a points multiplier.</p><form id="roster-movement-form"><label class="field">Type<select name="trainingType">${[['strength','Strength'],['bodyweight','Bodyweight & mobility'],['cardio','Cardio & endurance']].map(([key,label])=>`<option value="${key}" ${key===b.dataset.rosterLog?'selected':''}>${label}</option>`).join('')}</select></label>${field('Session name','name','Movement session')}<label class="field">Minutes (optional)<input name="minutes" type="number" min="1" max="600"></label><button class="primary wide" type="submit">Log completed session</button></form>`);}if(b.hasAttribute('data-roster-pause')){if(rosterPause){rosterPause=null;render();toast('Roster resumed. Your current routine is reflected again.');}else{rosterPause=date();render();toast('Roster paused. Take the time you need.');}}});
document.addEventListener('submit',e=>{if(e.target.id==='roster-quest-form'){e.preventDefault();const f=e.target,focus=new FormData(f).getAll('focus').map(Number);if(!focus.length){toast('Choose one focus that fits your life.');return;}run(async()=>{const i=Number(f.dataset.index),o=rosterQuestOptions[i];await save('quest',{name:o.name,rosterQuest:i,focus,start:date(),end:dayOffset(o.days-1)});closeModal();view='quests';location.hash=view;render();toast('Your chapter has begun.');});}if(e.target.id==='roster-movement-form'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));run(async()=>{await save('workout',{name:v.name,trainingType:v.trainingType,minutes:v.minutes?Number(v.minutes):null,date:selectedDate,status:'completed',unit:state.profile.unit,exercises:[],startedAt:null,finishedAt:null});closeModal();render();toast('Movement logged. Your roster reflects your rhythm.');});}});

// Guided workout prototype: one clear next action, with flexible exercise switching.
let flowRest=false,flowRestExercise=null;
function focusedSet(e){return e.sets.find(s=>!s.done);}
function nextExerciseIndex(w,index){for(let offset=1;offset<w.exercises.length;offset++){const i=(index+offset)%w.exercises.length;if(w.exercises[i].sets.some(s=>!s.done))return i;}return -1;}
function sessionPrevious(e,unit){return records('workout').filter(r=>r.value.status==='completed'&&r.value.unit===unit).flatMap(r=>r.value.exercises).find(x=>x.name.toLowerCase()===e.name.toLowerCase());}
function guidedWorkout(){const a=active();if(!a)return `<div class="page-heading"><div><span class="eyebrow">Training journal</span><h2>Your next chapter.</h2></div><button class="primary" data-action="start">Start workout</button></div><section class="card session-empty"><span class="eyebrow">READY WHEN YOU ARE</span><h3>A little focus.<br>A little stronger.</h3><p>Choose a workout. We’ll guide you through each set, with room to change the plan.</p><button class="primary" data-action="start">Choose a workout ${icon('arrow')}</button></section>${workoutHistory(records('workout').filter(r=>r.value.status==='completed'))}`;
 const w=a.value;if(!w.exercises.length)return '<section class="card"><button data-action="add-exercise">Add your first exercise</button></section>';currentExercise=Math.max(0,Math.min(currentExercise,w.exercises.length-1));const e=w.exercises[currentExercise],s=focusedSet(e),all=w.exercises.flatMap(x=>x.sets),done=all.filter(x=>x.done).length,completed=e.sets.filter(x=>x.done),next=nextExerciseIndex(w,currentExercise),prev=sessionPrevious(e,w.unit),resting=flowRest&&flowRestExercise===e.id,remaining=restPause||Math.max(0,Math.ceil((restUntil-Date.now())/1000));
 return `<div class="page-heading session-heading"><div><span class="eyebrow">${esc(w.name)}</span><h2>Find your flow.</h2></div><button class="quiet" data-action="finish">Finish session</button></div><section class="session-ribbon" aria-label="Session progress"><span>${icon('gym')} ${done} / ${all.length} sets logged</span><progress value="${done}" max="${all.length}" aria-label="Workout progress"></progress><button data-flow="switch">${w.exercises.filter(x=>x.sets.every(s=>s.done)).length} / ${w.exercises.length} exercises ${icon('arrow')}</button></section><div class="session-layout"><div class="session-workspace"><nav class="session-strip" aria-label="Exercise navigation"><button data-flow-exercise="${Math.max(0,currentExercise-1)}" ${currentExercise===0?'disabled':''} aria-label="Previous exercise">←<small>${currentExercise>0?esc(w.exercises[currentExercise-1].name):'Start of session'}</small></button><button data-flow="switch" aria-label="Choose exercise"><span>${String(currentExercise+1).padStart(2,'0')} / ${String(w.exercises.length).padStart(2,'0')}</span><strong>Exercise lineup</strong></button><button data-flow-exercise="${next}" ${next<0?'disabled':''} aria-label="Next unfinished exercise"><small>${next>=0?esc(w.exercises[next].name):(s?'Last exercise remaining':'All exercises logged')}</small>→</button></nav><section class="card session-focus ${resting?'session-is-resting':''}" aria-label="Current exercise"><div class="session-exercise-top"><span class="eyebrow">${resting?'MAKE ROOM FOR RECOVERY':s?'ONE SET AT A TIME':'EXERCISE LOGGED'}</span><button class="quiet" data-flow="tools" aria-label="Exercise tools">•••</button></div><h2>${esc(e.name)}</h2><div class="session-set-dots" aria-label="${completed.length} of ${e.sets.length} sets logged">${e.sets.map((x,i)=>`<span class="${x.done?'logged':x.id===s?.id?'current':''}">${x.done?icon('check'):i+1}</span>`).join('')}<button data-action="add-set" aria-label="Add another set">+</button></div>${resting?`<div class="session-rest-state"><span class="eyebrow">${restPause?'TIMER PAUSED':'TAKE A BREATH'}</span><div class="session-rest-clock" id="rest-clock">${Math.floor(remaining/60).toString().padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}</div><p>${s?'Next: set '+(e.sets.indexOf(s)+1)+' · adjust it while you rest.':next>=0?'Up next: '+esc(w.exercises[next].name):'Your planned sets are logged. Time to reflect.'}</p><div class="session-rest-controls"><button data-flow="pause" id="pause-rest">${restPause?'Resume timer':'Pause timer'}</button><button data-flow="extend">+30 sec</button></div></div>`:''}${s?`<form id="guided-set-form" data-set-id="${s.id}" class="session-set-form">${resting?`<details class="rest-next-plan"><summary>Adjust next set · ${s.weight} ${w.unit} × ${s.reps}</summary>`:""}<div class="session-entry-heading"><span>${resting?'PREPARE YOUR NEXT SET':'SET '+(e.sets.indexOf(s)+1)+' OF '+e.sets.length}</span><small>${prev?.sets[e.sets.indexOf(s)]?`Last time: ${prev.sets[e.sets.indexOf(s)].weight} ${w.unit} × ${prev.sets[e.sets.indexOf(s)].reps}`:completed.length?`Last set: ${completed.at(-1).weight} ${w.unit} × ${completed.at(-1).reps}`:'Your pace. Your starting point.'}</small></div><div class="session-inputs"><label>Weight <span>${w.unit}</span><input aria-label="Current set weight in ${w.unit}" name="weight" data-flow-field="weight" type="number" inputmode="decimal" min="0" max="1500" step="0.5" required value="${s.weight}"></label><label>Reps<input aria-label="Current set reps" name="reps" data-flow-field="reps" type="number" inputmode="numeric" min="1" max="200" step="1" required value="${s.reps}"></label></div><details class="session-effort"><summary>Add effort · optional</summary><label class="field">Effort (RPE, 1–10)<input name="rpe" aria-label="Current set effort" data-flow-field="rpe" type="number" min="1" max="10" step="0.5" value="${s.rpe??''}" placeholder="How hard did it feel?"></label></details>${resting?"</details>":""}<div class="session-action-bar"><button class="primary" type="${resting?'button':'submit'}" ${resting?'data-flow="ready"':''}>${resting?'Ready for this set':`Log set ${e.sets.indexOf(s)+1}`} ${icon(resting?'arrow':'check')}</button><span>${resting?'Skip the remaining rest whenever you are ready.':'One tap saves your set and starts rest.'}</span></div></form>`:`<div class="session-exercise-complete"><span class="session-complete-symbol">${icon('check')}</span><h3>${next>=0?'A little stronger. On we go.':'You made space for yourself.'}</h3><p>${completed.length} sets logged for this exercise.</p><div class="session-action-bar"><button class="primary" data-flow="${next>=0?'next':'review'}">${next>=0?'Next exercise · '+esc(w.exercises[next].name):'Review & finish session'} ${icon('arrow')}</button><span>${resting?'Move on when you’re ready.':'Your logged sets stay editable below.'}</span></div></div>`}<details class="session-logged-sets"><summary>Logged sets · ${completed.length} <span>Review or correct</span></summary>${completed.map(x=>`<div><span>Set ${e.sets.indexOf(x)+1}</span><strong>${x.weight} ${w.unit} × ${x.reps}${x.rpe?' · RPE '+x.rpe:''}</strong><button data-flow-edit="${x.id}">Edit</button></div>`).join('')||'<p class="subtle">Your first logged set will appear here.</p>'}</details><button class="session-busy-link" data-flow="switch">Equipment busy? Do another exercise ${icon('arrow')}</button></section></div><aside class="session-side"><section class="card"><span class="eyebrow">YOUR SESSION</span><h3>The bigger picture.</h3><div class="detail-line"><span>Sets logged</span><strong>${done} / ${all.length}</strong></div><div class="detail-line"><span>Volume logged</span><strong>${all.filter(x=>x.done).reduce((sum,x)=>sum+x.weight*x.reps,0).toLocaleString()} ${w.unit}</strong></div><p class="subtle">Change the order whenever you need. Unfinished sets stay in your session.</p><button class="quiet wide" data-flow="switch">View exercise lineup</button></section><section class="card session-tip"><span class="eyebrow">A LITTLE REMINDER</span><p>Rest is part of the work.<br>There’s no rush to the next set.</p></section></aside></div>`;
}
function switchFlowExercise(i){const a=active();if(!a||i<0||i>=a.value.exercises.length)return;currentExercise=i;flowRest=false;restUntil=restPause=0;closeModal();render();document.querySelector('.session-strip')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function guidedClock(){const remain=restPause||Math.max(0,Math.ceil((restUntil-Date.now())/1000)),el=$('#rest-clock');if(el)el.textContent=remain?`${Math.floor(remain/60).toString().padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`:'Ready';if(flowRest&&!restPause&&restUntil&&Date.now()>=restUntil){flowRest=false;restUntil=0;if(view==='workouts'){const field=document.activeElement?.dataset.flowField;render();if(field)document.querySelector('[data-flow-field="'+field+'"]')?.focus({preventScroll:true});}}const b=$('#pause-rest');if(b)b.textContent=restPause?'Resume timer':'Pause timer';}
function exerciseSwitcher(){const w=active().value;modal('Your session. Your order.',`<p class="subtle">Switch whenever you need. Your logged sets and planned values stay in place.</p><div class="session-switcher">${w.exercises.map((e,i)=>`<button data-flow-exercise="${i}" ${i===currentExercise?'aria-current="true"':''}><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(e.name)}</strong><small>${e.sets.filter(s=>s.done).length} / ${e.sets.length} sets logged ${i===currentExercise?'· current':''}</small></div>${icon(e.sets.every(s=>s.done)?'check':'arrow')}</button>`).join('')}</div><button class="quiet wide" data-action="add-exercise">Add an exercise</button>`);}
function editGuidedSet(id){const w=active().value,e=w.exercises.find(e=>e.sets.some(s=>s.id===id)),s=e?.sets.find(s=>s.id===id);if(!s)return;modal('Correct your set',`<p class="subtle">${esc(e.name)} · set ${e.sets.indexOf(s)+1}</p><form id="guided-edit-form" data-set-id="${id}">${field('Weight ('+w.unit+')','weight',s.weight,'number','min="0" max="1500" step="0.5"')}${field('Reps','reps',s.reps,'number','min="1" max="200" step="1"')}<label class="field">Effort (optional)<input name="rpe" type="number" min="1" max="10" step="0.5" value="${s.rpe??''}"></label><button type="submit" class="primary wide">Save correction</button><button type="button" class="quiet wide" data-flow-reopen="${id}">Reopen this set</button></form>`);}
function sessionRecap(w,before){const sets=w.exercises.flatMap(e=>e.sets).filter(s=>s.done),roster=rosterStatus(),joined=roster.filter(p=>p.active&&!before.has(p.index));modal('A little effort. A lasting change.',`<span class="eyebrow">SESSION COMPLETE</span><h3>${esc(w.name)}</h3><div class="session-recap-metrics"><div><strong>${sets.length}</strong><span>sets logged</span></div><div><strong>${w.exercises.filter(e=>e.sets.some(s=>s.done)).length}</strong><span>exercises trained</span></div><div><strong>${sets.reduce((sum,s)=>sum+s.weight*s.reps,0).toLocaleString()}</strong><span>${w.unit} volume</span></div></div><h3>Your roster, reflected.</h3><p>${joined.length?joined.map(p=>p.name).join(' & ')+' joined your roster.':`This session adds a movement day to your rhythm. Multiple sessions on one day count once.`}</p><div class="session-recap-roster">${roster.filter(p=>p.active).map(p=>`<button data-roster-persona="${p.index}">${rosterPortrait(p.index,true)}<span>${p.name}</span></button>`).join('')}</div><p class="subtle">Unlogged sets stay unlogged. Rest and nourishment can be your next chapter.</p><div class="button-row"><button class="primary" data-flow="recap-home">Back to Today</button><button class="quiet" data-flow="recap-grow">View roster</button></div>`);}
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.flowField)return;const a=active(),s=a?.value.exercises[currentExercise]?.sets.find(s=>s.id===$('#guided-set-form')?.dataset.setId);if(s)s[el.dataset.flowField]=el.value===''?null:Number(el.value);});
document.addEventListener('submit',e=>{const f=e.target;if(!['guided-set-form','guided-edit-form'].includes(f.id))return;e.preventDefault();if(f.id==='guided-set-form'&&flowRest)return;run(async()=>{const a=active(),v=structuredClone(a.value),ex=v.exercises.find(e=>e.sets.some(s=>s.id===f.dataset.setId)),s=ex.sets.find(s=>s.id===f.dataset.setId),data=Object.fromEntries(new FormData(f));s.weight=Number(data.weight);s.reps=Number(data.reps);s.rpe=data.rpe===''?null:Number(data.rpe);if(!Number.isFinite(s.weight)||s.weight<0||s.weight>1500||!Number.isInteger(s.reps)||s.reps<1||s.reps>200||s.rpe!==null&&(!Number.isFinite(s.rpe)||s.rpe<1||s.rpe>10))throw Error('Check weight, reps and effort before saving.');if(f.id==='guided-set-form'){if(s.done)return;s.done=true;const upcoming=focusedSet(ex);if(upcoming){upcoming.weight=s.weight;upcoming.reps=s.reps;upcoming.rpe=null;}await save('workout',v,a);flowRest=ex.rest>0;flowRestExercise=ex.id;restUntil=Date.now()+ex.rest*1000;restPause=0;render();toast('Set logged. Take a breath.');}else{await save('workout',v,a);closeModal();render();toast('Set corrected.');}});});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.flowExercise!==undefined){switchFlowExercise(Number(b.dataset.flowExercise));return;}if(b.dataset.flowEdit){editGuidedSet(b.dataset.flowEdit);return;}if(b.dataset.flowReopen){run(async()=>{const a=active(),v=structuredClone(a.value),ex=v.exercises.find(e=>e.sets.some(s=>s.id===b.dataset.flowReopen));ex.sets.find(s=>s.id===b.dataset.flowReopen).done=false;currentExercise=v.exercises.indexOf(ex);await save('workout',v,a);flowRest=false;restUntil=restPause=0;closeModal();render();toast('Set reopened.');});return;}const act=b.dataset.flow;if(!act)return;if(act==='switch')exerciseSwitcher();if(act==='next')switchFlowExercise(nextExerciseIndex(active().value,currentExercise));if(act==='ready'){flowRest=false;restUntil=restPause=0;render();}if(act==='pause'){if(restPause){restUntil=Date.now()+restPause*1000;restPause=0;}else{restPause=Math.max(1,Math.ceil((restUntil-Date.now())/1000));restUntil=0;}render();}if(act==='extend'){if(restPause)restPause+=30;else restUntil=Math.max(Date.now(),restUntil)+30000;guidedClock();}if(act==='review')document.querySelector('[data-action="finish"]')?.click();if(act==='tools'){const ex=active().value.exercises[currentExercise];modal('Exercise tools',`<h3>${esc(ex.name)}</h3><form id="session-tools-form">${field('Exercise name','name',ex.name)}${field('Rest between sets (seconds)','rest',ex.rest,'number','min="0" max="900" step="1"')}<button class="primary wide" type="submit">Save exercise</button></form><button class="quiet wide" data-flow="plates">Plate calculator</button>`);}if(act==='plates')modal('Plate calculator',`<label class="field">Total weight<input id="plate-total" type="number" min="0" value="${active().value.unit==='kg'?60:135}"></label><label class="field">Bar weight<input id="plate-bar" type="number" min="0" value="${active().value.unit==='kg'?20:45}"></label><button class="primary wide" data-action="plates">Calculate</button><div id="plate-result" class="plate-result"></div>`);if(act==='recap-home'||act==='recap-grow'){closeModal();view=act==='recap-home'?'overview':'quests';location.hash=view;render();window.scrollTo(0,0);}});
document.addEventListener('submit',e=>{if(e.target.id!=='session-tools-form')return;e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));run(async()=>{const a=active(),v=structuredClone(a.value);v.exercises[currentExercise].name=data.name;v.exercises[currentExercise].rest=Number(data.rest);await save('workout',v,a);closeModal();render();});});
